import{_ as l,H as e,f as i,i as r}from"./chunks/framework.Cvt1eIE0.js";const b=JSON.parse('{"title":"爵位・軍位・特権","description":"","frontmatter":{"title":"爵位・軍位・特権","outline":"deep"},"headers":[],"relativePath":"ranks.md","filePath":"ranks.md"}'),h={name:"ranks.md"};function t(o,a,n,d,u,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="爵位・軍位・特権" tabindex="-1">爵位・軍位・特権 <a class="header-anchor" href="#爵位・軍位・特権" aria-label="Permalink to &quot;爵位・軍位・特権&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PIGLIN KINGDOM における身分制度、軍位、栄誉及び特権を定める。</p></div><h1 id="第一編-爵位制度" tabindex="-1">第一編 爵位制度 <a class="header-anchor" href="#第一編-爵位制度" aria-label="Permalink to &quot;第一編 爵位制度&quot;">​</a></h1><h2 id="第一章-貴族" tabindex="-1">第一章 貴族 <a class="header-anchor" href="#第一章-貴族" aria-label="Permalink to &quot;第一章 貴族&quot;">​</a></h2><h3 id="公爵" tabindex="-1">公爵 <a class="header-anchor" href="#公爵" aria-label="Permalink to &quot;公爵&quot;">​</a></h3><p>王国最高位の貴族。</p><p>特権</p><ul><li>公爵家の紋章を使用できる。</li><li>王立評議会へ出席できる。</li><li>宮殿への自由な立ち入りを認める。</li></ul><h3 id="侯爵" tabindex="-1">侯爵 <a class="header-anchor" href="#侯爵" aria-label="Permalink to &quot;侯爵&quot;">​</a></h3><p>辺境や重要地域を統治する貴族。</p><p>特権</p><ul><li>私兵団の保有を認める。</li><li>王国儀式に参列できる。</li></ul><h3 id="伯爵" tabindex="-1">伯爵 <a class="header-anchor" href="#伯爵" aria-label="Permalink to &quot;伯爵&quot;">​</a></h3><p>州を統治する上級貴族。</p><p>特権</p><ul><li>伯爵家の旗を掲げられる。</li><li>王国勲章を授与できる。</li></ul><h3 id="子爵" tabindex="-1">子爵 <a class="header-anchor" href="#子爵" aria-label="Permalink to &quot;子爵&quot;">​</a></h3><p>地方都市を管理する貴族。</p><p>特権</p><ul><li>儀礼用の護衛を持つことができる。</li></ul><h3 id="男爵" tabindex="-1">男爵 <a class="header-anchor" href="#男爵" aria-label="Permalink to &quot;男爵&quot;">​</a></h3><p>最下位の貴族。</p><p>特権</p><ul><li>男爵家の紋章を使用できる。</li></ul><hr><h1 id="第二編-騎士階級" tabindex="-1">第二編 騎士階級 <a class="header-anchor" href="#第二編-騎士階級" aria-label="Permalink to &quot;第二編 騎士階級&quot;">​</a></h1><h2 id="第一章-騎士" tabindex="-1">第一章 騎士 <a class="header-anchor" href="#第一章-騎士" aria-label="Permalink to &quot;第一章 騎士&quot;">​</a></h2><h3 id="王立騎士" tabindex="-1">王立騎士 <a class="header-anchor" href="#王立騎士" aria-label="Permalink to &quot;王立騎士&quot;">​</a></h3><p>特権</p><ul><li>騎士の称号を名乗ることができる。</li><li>儀礼用の剣を帯びることができる。</li><li>王宮の謁見権を有する。</li></ul><h3 id="名誉騎士" tabindex="-1">名誉騎士 <a class="header-anchor" href="#名誉騎士" aria-label="Permalink to &quot;名誉騎士&quot;">​</a></h3><p>特権</p><ul><li>名誉称号を生涯保持する。</li><li>王国の公式行事へ招待される。</li></ul><hr><h1 id="第三編-軍位" tabindex="-1">第三編 軍位 <a class="header-anchor" href="#第三編-軍位" aria-label="Permalink to &quot;第三編 軍位&quot;">​</a></h1><h2 id="第一章-将官" tabindex="-1">第一章 将官 <a class="header-anchor" href="#第一章-将官" aria-label="Permalink to &quot;第一章 将官&quot;">​</a></h2><h3 id="元帥" tabindex="-1">元帥 <a class="header-anchor" href="#元帥" aria-label="Permalink to &quot;元帥&quot;">​</a></h3><p>王国軍最高位。</p><p>特権</p><ul><li>黄金元帥杖を携行できる。</li><li>国王への直接上申権を有する。</li></ul><h3 id="大将" tabindex="-1">大将 <a class="header-anchor" href="#大将" aria-label="Permalink to &quot;大将&quot;">​</a></h3><p>特権</p><ul><li>軍集団を指揮できる。</li></ul><h3 id="中将" tabindex="-1">中将 <a class="header-anchor" href="#中将" aria-label="Permalink to &quot;中将&quot;">​</a></h3><p>特権</p><ul><li>軍団を指揮できる。</li></ul><h3 id="少将" tabindex="-1">少将 <a class="header-anchor" href="#少将" aria-label="Permalink to &quot;少将&quot;">​</a></h3><p>特権</p><ul><li>師団を指揮できる。</li></ul><hr><h2 id="第二章-士官" tabindex="-1">第二章 士官 <a class="header-anchor" href="#第二章-士官" aria-label="Permalink to &quot;第二章 士官&quot;">​</a></h2><h3 id="大佐" tabindex="-1">大佐 <a class="header-anchor" href="#大佐" aria-label="Permalink to &quot;大佐&quot;">​</a></h3><p>特権</p><ul><li>連隊を指揮できる。</li></ul><h3 id="中佐" tabindex="-1">中佐 <a class="header-anchor" href="#中佐" aria-label="Permalink to &quot;中佐&quot;">​</a></h3><p>特権</p><ul><li>大隊を指揮できる。</li></ul><h3 id="少佐" tabindex="-1">少佐 <a class="header-anchor" href="#少佐" aria-label="Permalink to &quot;少佐&quot;">​</a></h3><p>特権</p><ul><li>中隊を指揮できる。</li></ul><h3 id="大尉" tabindex="-1">大尉 <a class="header-anchor" href="#大尉" aria-label="Permalink to &quot;大尉&quot;">​</a></h3><p>特権</p><ul><li>小隊を指揮できる。</li></ul><hr><h2 id="第三章-下士官" tabindex="-1">第三章 下士官 <a class="header-anchor" href="#第三章-下士官" aria-label="Permalink to &quot;第三章 下士官&quot;">​</a></h2><h3 id="軍曹" tabindex="-1">軍曹 <a class="header-anchor" href="#軍曹" aria-label="Permalink to &quot;軍曹&quot;">​</a></h3><p>特権</p><ul><li>部隊の訓練を担当する。</li></ul><h3 id="伍長" tabindex="-1">伍長 <a class="header-anchor" href="#伍長" aria-label="Permalink to &quot;伍長&quot;">​</a></h3><p>特権</p><ul><li>分隊を指揮できる。</li></ul><hr><h2 id="第四章-兵" tabindex="-1">第四章 兵 <a class="header-anchor" href="#第四章-兵" aria-label="Permalink to &quot;第四章 兵&quot;">​</a></h2><h3 id="上等兵" tabindex="-1">上等兵 <a class="header-anchor" href="#上等兵" aria-label="Permalink to &quot;上等兵&quot;">​</a></h3><p>優秀な兵士。</p><h3 id="一等兵" tabindex="-1">一等兵 <a class="header-anchor" href="#一等兵" aria-label="Permalink to &quot;一等兵&quot;">​</a></h3><p>一般兵士。</p><h3 id="新兵" tabindex="-1">新兵 <a class="header-anchor" href="#新兵" aria-label="Permalink to &quot;新兵&quot;">​</a></h3><p>入隊直後の兵士。</p><hr><h1 id="第四編-栄典" tabindex="-1">第四編 栄典 <a class="header-anchor" href="#第四編-栄典" aria-label="Permalink to &quot;第四編 栄典&quot;">​</a></h1><h2 id="第一章-勲章" tabindex="-1">第一章 勲章 <a class="header-anchor" href="#第一章-勲章" aria-label="Permalink to &quot;第一章 勲章&quot;">​</a></h2><h3 id="黄金十字勲章" tabindex="-1">黄金十字勲章 <a class="header-anchor" href="#黄金十字勲章" aria-label="Permalink to &quot;黄金十字勲章&quot;">​</a></h3><p>軍事的功績に対して授与する。</p><p>特典</p><ul><li>生涯年金を支給する。</li></ul><h3 id="王国功労勲章" tabindex="-1">王国功労勲章 <a class="header-anchor" href="#王国功労勲章" aria-label="Permalink to &quot;王国功労勲章&quot;">​</a></h3><p>国家への功績に対して授与する。</p><p>特典</p><ul><li>王国行事への優先招待。</li></ul><h3 id="黄金賞" tabindex="-1">黄金賞 <a class="header-anchor" href="#黄金賞" aria-label="Permalink to &quot;黄金賞&quot;">​</a></h3><p>科学技術への貢献に対して授与する。</p><hr><h1 id="第五編-特権及び免除" tabindex="-1">第五編 特権及び免除 <a class="header-anchor" href="#第五編-特権及び免除" aria-label="Permalink to &quot;第五編 特権及び免除&quot;">​</a></h1><h2 id="第一章-税の優遇" tabindex="-1">第一章 税の優遇 <a class="header-anchor" href="#第一章-税の優遇" aria-label="Permalink to &quot;第一章 税の優遇&quot;">​</a></h2><h3 id="貴族" tabindex="-1">貴族 <a class="header-anchor" href="#貴族" aria-label="Permalink to &quot;貴族&quot;">​</a></h3><ul><li>相続税を免除する。</li></ul><h3 id="名誉国民" tabindex="-1">名誉国民 <a class="header-anchor" href="#名誉国民" aria-label="Permalink to &quot;名誉国民&quot;">​</a></h3><ul><li>王立施設の利用料を免除する。</li></ul><h3 id="勲章受章者" tabindex="-1">勲章受章者 <a class="header-anchor" href="#勲章受章者" aria-label="Permalink to &quot;勲章受章者&quot;">​</a></h3><ul><li>国家行事への参加費を免除する。</li></ul><hr><h2 id="第二章-王宮特権" tabindex="-1">第二章 王宮特権 <a class="header-anchor" href="#第二章-王宮特権" aria-label="Permalink to &quot;第二章 王宮特権&quot;">​</a></h2><h3 id="王族" tabindex="-1">王族 <a class="header-anchor" href="#王族" aria-label="Permalink to &quot;王族&quot;">​</a></h3><ul><li>王宮全域への立ち入りを認める。</li></ul><h3 id="公爵-1" tabindex="-1">公爵 <a class="header-anchor" href="#公爵-1" aria-label="Permalink to &quot;公爵&quot;">​</a></h3><ul><li>王宮の貴族区域へ入ることができる。</li></ul><h3 id="王立騎士-1" tabindex="-1">王立騎士 <a class="header-anchor" href="#王立騎士-1" aria-label="Permalink to &quot;王立騎士&quot;">​</a></h3><ul><li>謁見の間への立ち入りを認める。</li></ul><hr><h2 id="第三章-軍人の特権" tabindex="-1">第三章 軍人の特権 <a class="header-anchor" href="#第三章-軍人の特権" aria-label="Permalink to &quot;第三章 軍人の特権&quot;">​</a></h2><h3 id="将官" tabindex="-1">将官 <a class="header-anchor" href="#将官" aria-label="Permalink to &quot;将官&quot;">​</a></h3><ul><li>儀礼用軍刀の携行を認める。</li><li>優先輸送を受けられる。</li></ul><h3 id="退役軍人" tabindex="-1">退役軍人 <a class="header-anchor" href="#退役軍人" aria-label="Permalink to &quot;退役軍人&quot;">​</a></h3><ul><li>王立病院を優先利用できる。</li></ul><h3 id="戦傷者" tabindex="-1">戦傷者 <a class="header-anchor" href="#戦傷者" aria-label="Permalink to &quot;戦傷者&quot;">​</a></h3><ul><li>終身年金を受給できる。</li></ul><hr><h1 id="第六編-栄誉称号" tabindex="-1">第六編 栄誉称号 <a class="header-anchor" href="#第六編-栄誉称号" aria-label="Permalink to &quot;第六編 栄誉称号&quot;">​</a></h1><h3 id="王国英雄" tabindex="-1">王国英雄 <a class="header-anchor" href="#王国英雄" aria-label="Permalink to &quot;王国英雄&quot;">​</a></h3><p>国家最高の名誉称号。</p><h3 id="名誉国民-1" tabindex="-1">名誉国民 <a class="header-anchor" href="#名誉国民-1" aria-label="Permalink to &quot;名誉国民&quot;">​</a></h3><p>特別な功績を持つ者に授与する。</p><h3 id="名誉騎士-1" tabindex="-1">名誉騎士 <a class="header-anchor" href="#名誉騎士-1" aria-label="Permalink to &quot;名誉騎士&quot;">​</a></h3><p>文化・科学・外交への功績者に授与する。</p><h3 id="王国の守護者" tabindex="-1">王国の守護者 <a class="header-anchor" href="#王国の守護者" aria-label="Permalink to &quot;王国の守護者&quot;">​</a></h3><p>王国防衛において顕著な功績を挙げた者に授与する。</p><hr><blockquote><p>名誉は黄金より重く、</p><p>忠誠は剣より強く、</p><p>栄光は永遠に語り継がれる。</p></blockquote>',129)])])}const q=l(h,[["render",t]]);export{b as __pageData,q as default};
